# Euro area raw inputs (Compass). Sources noted per series.
def _p(s): return {k:float(v) for k,v in (x.split(':') for x in s.split(','))}
def seq(start_year, vals, start_month=1):
    out={}
    for i,v in enumerate(vals):
        t=start_year*12+start_month-1+i; out[f'{t//12}-{t%12+1:02d}']=v
    return out
